import { loadEnv, botToken, DISCORD_API, ROOTMC_GUILD_ID, AVA_CHANNELS } from "../src/config.mjs";
import { authHeaders } from "../src/discordApi.mjs";

const env = await loadEnv();
const token = botToken(env);
const headers = authHeaders(token);

const GENERAL = "1516108586307158088";
const UPDATES = "1520665313631408251";
const GUILD = ROOTMC_GUILD_ID;
const MELEE_MSG = "1532927677798023288";
const STAFF_ROLE_ID = "1516121138420252803";
const EVERYONE_ID = GUILD; // @everyone overwrite id = guild id

const VIEW = 1n << 10n;
const SEND = 1n << 11n;
const READ_HISTORY = 1n << 16n;
const ATTACH_FILES = 1n << 15n;
const MANAGE_MESSAGES = 1n << 13n;
const PIN_MESSAGES = 1n << 24n;
const USE_APP_CMD = 1n << 31n;
const CREATE_PUB_THREAD = 1n << 35n;
const SEND_IN_THREAD = 1n << 38n;

function perm(...bits) {
  return bits.reduce((a, b) => a | b, 0n).toString();
}

async function api(method, route, body) {
  const res = await fetch(`${DISCORD_API}${route}`, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`${method} ${route} -> ${res.status}: ${text.slice(0, 400)}`);
  return text ? JSON.parse(text) : null;
}

async function post(channelId, content, refId, { everyone = false } = {}) {
  const textBody = everyone
    ? `@everyone\n${String(content)}`.slice(0, 2000)
    : String(content).slice(0, 2000);
  return api("POST", `/channels/${channelId}/messages`, {
    content: textBody,
    message_reference: refId ? { message_id: refId } : undefined,
